quests[13679] = { id = 13679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against a skilled opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your horse be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against an experienced opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your mount be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chip Off the Ulduar Block", description = "Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.'\n\nAnyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.", sourceObjective = "Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get that stone?", completion = "These should do. Just don't go around blabbing to those crusaders about where you got them from. I'm sure they'll get upset. But, hey, it's not like the titans have come back for them. They're fair game, I say. Good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", progress = "Have you defeated the Cult of the Damned raiding party?", completion = "{name}, you and your allies have spared the tournament from a devastating attack. Though our skytalon riders are brave, they  have their hands full keeping the peace on the tournament grounds and would be hard-pressed to defend the skies against the cult's attack. You have the thanks of the Argent Crusade and all who have gathered here to compete.", sourceObjectiveStatus = "unverified-source-field" }
quests[13683] = { id = 13683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Rituals", description = "I could not help but overhear Illiyana's loss. I understand her need for revenge. I am wondering if while you are exacting it, you could do us a service?\n\nNo doubt you have already seen the satyr of Satyrnaar and Xavian conducting vile rituals. I believe that they are preparing their rituals to corrupt any of the night elves they capture, turning them into satyrs. We draenei also have problems with fel magic exposure.\n\nWould you disturb their ritual gems while you are there?", sourceObjective = "Disturb 8 Ritual Gems.", progress = "Please see to it that you disturb as many of the ritual gems as you can.\n\nThe last thing that we want is for any of the draenei here to be twisted into one of the Broken, or the elves to be corrupted into more satyrs.", completion = "We are in your debt, {class}.\n\nUnable to complete their nefarious rituals, the satyr are now fighting a losing battle where they are unable to replenish their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Stormwind", description = "You've proven yourself worthy of competing under the banner of Stormwind, {name}. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Marshal Jacob Alerius at the Argent Tournament Grounds to become a valiant of Stormwind.", completion = "Welcome aboard then, Valiant {name}. The Stormwind delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Ironforge", description = "You've proven yourself worthy of competing under the banner of Ironforge, {name}. Now, you should introduce yourself to Lana Stouthammer, who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Lana Stouthammer at the Argent Tournament Grounds to become a valiant of Ironforge.", completion = "It's good to meet you, valiant. Ironforge needs competitors like you to prevail in the tournament.", sourceObjectiveStatus = "unverified-source-field" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Gnomeregan", description = "You've proven yourself worthy of competing under the banner of Gnomeregan, {name}. Now, you should introduce yourself to Ambrose Boltspark, who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Ambrose Boltspark at the Argent Tournament Grounds to become a valiant of Gnomeregan.", completion = "Welcome aboard then, Valiant {name}. The Gnomeregan delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Darnassus", description = "You've proven yourself worthy of competing under the banner of Darnassus, {name}. Now, you should introduce yourself to Jaelyne Evensong, who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Jaelyne Evensong at the Argent Tournament Grounds to become a valiant of Darnassus.", completion = "Welcome to the Darnassus tournament delegation, {name}. It will be a pleasure to train and compete alongside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of The Exodar", description = "You've proven yourself worthy of competing under the banner of the Exodar, {name}. Now, you should introduce yourself to Colosos, who leads the Exodar delegation. As the draenei grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Colosos at the Argent Tournament Grounds to become a valiant of the Exodar.", completion = "Welcome aboard then, Valiant {name}. The Exodar's delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Orgrimmar", description = "You've proven yourself worthy of competing under the banner of Orgrimmar, {name}. Now, you should speak with Mokra the Skullcrusher, who leads Orgrimmar's competitors. As Orgrimmar's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Mokra the Skullcrusher at the Argent Tournament Grounds to become a valiant of Orgrimmar.", completion = "So you want to compete for Orgrimmar? Just because you've beaten up a few dummies doesn't mean you'll win, but you'll be training with the best from now on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword and the Sea", description = "My sword was lost at sea.  Catch it and bring it back!", sourceObjective = "Old Man Barlo in Crystalsong Forest wants you to bring him the Sword of Knighthood.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Sen'jin", description = "You've proven yourself worthy of competing under the banner of Sen'jin, {name}. Now, you should speak with Zul'tore who leads Sen'jin's warriors. As the troll grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Zul'tore at the Argent Tournament Grounds to become a valiant of Sen'jin.", completion = "You think you have what it takes to compete for Sen'jin? I think we'll be finding out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Thunder Bluff", description = "You've proven yourself worthy of competing under the banner of Thunder Bluff, {name}. Now, you should speak with Runok Wildmane, who leads Thunder Bluff's competitors. As Thunder Bluff's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Runok Wildmane at the Argent Tournament Grounds to become a valiant of Thunder Bluff.", completion = "On behalf of Thunder Bluff and its warriors, I welcome you, {name}. Always fight honorably and bravely beneath our banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Undercity", description = "You've proven yourself worthy of competing under the banner of the Undercity, {name}. Now, you should speak with Deathstalker Visceri, who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Deathstalker Visceri at the Argent Tournament Grounds to become a valiant of the Undercity.", completion = "Welcome to the Undercity delegation. {name}. As a valiant, you'll train with us to prepare you for the highest level of competition.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Silvermoon", description = "You've proven yourself worthy of competing under the banner of Silvermoon, {name}. Now, you should speak with Eressea Dawnsinger, who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Eressea Dawnsinger at the Argent Tournament Grounds to become a valiant of Silvermoon.", completion = "So you want to compete for Silvermoon? Very well. I'll add you to the rolls and you may begin working with the other valiants immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13698] = { id = 13698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosives Shredding", description = "I hate to send you back in there, but based on your description of what's going on, we can't let them use all of those explosives they have stored up!\n\nIt's too dangerous for you to try to destroy them yourself, but if you were to steal one of their shredders, I'm sure they're tough enough to withstand the explosions.\n\nAfter you've destroyed their explosives, return here with the shredder. There's no sense in letting them have it back.", sourceObjective = "Use a Warsong Shredder to destroy 8 Kegs of Explosives.", progress = "Time's running out, {name}.", completion = "I saw those explosions all of the way from over here! Those filthy orcs and their goblin lackeys are going to have a hard time doing anything to despoil the forest now!\n\nWe can't thank you enough, {name}. Will this do?", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Stormwind, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13703] = { id = 13703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Ironforge", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.", completion = "We are proud that you have decided to join us and I know you will shine on the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Gnomeregan", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a {class} like you.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.", completion = "We're proud to count you among us, {name}, and we look forward to training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of The Exodar", description = "Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Colosos again if you wish to become a valiant of the Exodar.", completion = "It's good to have you on our team, {name}. We will all benefit from training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Darnassus", description = "Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.", completion = "The warriors of Darnassus are honored to fight and train beside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Orgrimmar", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.", completion = "Welcome, then, {name}. I look forward to watching you train with my men.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Sen'jin", description = "Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Zul'tore again if you wish to become a valiant of Sen'jin.", completion = "I am glad that you have decided to join us and look forward to seeing you in action.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Thunder Bluff", description = "Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Runok Wildmane again if you wish to become a valiant of Thunder Bluff.", completion = "I am honored that you have chosen to join our delegation. I know you will make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Undercity", description = "Welcome, champion. The Forsaken delegation could always use more {class}s like you. Would you join us?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Deathstalker Visceri again if you wish to become a valiant of the Undercity.", completion = "You have chosen wisely, {name}. Both of us will benefit from this arrangement.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Silvermoon", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Eressea Dawnsinger again if you wish to become a valiant of Silvermoon.", completion = "It will be an honor training and competing with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13712] = { id = 13712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rescue!", description = "You're coming with me, {name}.\n\nThere's no one else that I can spare, and we cannot afford for Splintertree to be lost.\n\nPrepare yourself, and speak to me again when you are ready.", sourceObjective = "Speak to Kadrak at Mor'shan Ramparts and accompany him to Splintertree Post.", progress = "Work complete!", completion = "Gorka's death was not in vain, {name}.\n\nSplintertree would have certainly fallen if we hadn't come when we did.\n\nNow we must get to work shoring up her defenses.\n\nThis isn't over....", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Lana Stouthammer at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Ironforge, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13714] = { id = 13714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13715] = { id = 13715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
