quests[13739] = { id = 13739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Forsaken!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13740] = { id = 13740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Silvermoon!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13741] = { id = 13741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13742] = { id = 13742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The grand champion accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13743] = { id = 13743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Lana Stouthammer at the Argent Tournament Grounds wants you to bring her Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13744] = { id = 13744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Rollo Sureshot at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13745] = { id = 13745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Ironforge are looking forward to hearing of our success. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same. The valiants practice in the ring just outside our tent. Equip your lance, go to the stables outside the pavilion and mount the stabled Ironforge ram, then challenge other Alliance valiants.", sourceObjective = "Bring 3 Marks of the Valiant to Clara Tumblebrew at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Ironforge proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13746] = { id = 13746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13747] = { id = 13747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<Ambrose accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13748] = { id = 13748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Ambrose Boltspark at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13749] = { id = 13749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Tickin Gearspanner at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", progress = "Have you tested yourself in combat against the Scourge?", completion = "Welcome back from your exercises, {name}. I'm confident that you will make us proud when the competition starts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13750] = { id = 13750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. We know everyone's looking forward to seeing us in the competition. To that end, we've been honing our skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Flickin Gearspanner at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13751] = { id = 13751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell No One!", description = "Perfect!\n\nThis will show the elves what the Horde is capable of when we're backed into a corner.\n\nListen, {name}. You must say nothing of this to anyone!\n\nGarrosh will surely approve once he sees the results, but if we are found out beforehand, our heads will be placed on spikes!\n\n<Draaka hands you a hastily written note.>\n\nBring this to Durak. You can find him in the mines behind me, just to the north. He will instruct you further.", sourceObjective = "Draaka in Splintertree wants you to bring the Hastily Written Note to Durak.\n\nProvided item:", completion = "What's this? Who are you!?\n\n<Durak reads Draaka's note.>\n\nHrmphh...\n\nDraaka should know better than to be so brazen, but it looks like you're up to your eyes in this with as much to lose as anyone.\n\nVery well.", sourceObjectiveStatus = "unverified-source-field" }
quests[13752] = { id = 13752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Colosos at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13753] = { id = 13753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing.I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Colosos at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The grand champion accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13754] = { id = 13754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Colosos at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13755] = { id = 13755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Saandos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", progress = "Have you tested yourself in combat against the Scourge?", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13756] = { id = 13756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of the Exodar are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Azuremyst elekk, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Ranii at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13757] = { id = 13757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Jaelyne Evensong at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13758] = { id = 13758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck! My blade is missing!\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Jaelyne Evensong at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<Jaelyne accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13759] = { id = 13759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Jaelyne Evensong at the Argent Tournament Grounds wants you to bring her Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13760] = { id = 13760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Illestria Bladesinger at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13761] = { id = 13761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Darnassus are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nThe Alliance Valiants' Ring is just outside our tent. Go to the stables on the outside the pavilion, equip your lance, mount the stabled Darnassian mistsaber, and challenge the valiants.", sourceObjective = "Bring 3 Marks of the Valiant to Airae Starseeker at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Darnassus proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13762] = { id = 13762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", sourceObjectiveStatus = "unverified-source-field" }
quests[13763] = { id = 13763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13764] = { id = 13764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Mokra the Skullcrusher at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13765] = { id = 13765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Akinos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", progress = "Have you tested yourself in combat against the Scourge?", completion = "A good day of training will never hurt anyone. It's good to see you keeping up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13766] = { id = 13766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closure is Only Natural", description = "Through the ground I can feel more demons being brought into our world. Soon there will be too many and we will be overrun without hope of turning them back.\n\nTake this piece of me and return to Demon Fall Canyon and Demon Fall Ridge, south of Felfire Hill. Aim the bough at a demon gate and concentrate. I have stored a portion of the forest's life force in its wood, and it will close the gate.", sourceObjective = "Use Gnarl's Bough to close 10 Demon Gates.", completion = "With their gates closed and no further reinforcements coming, it is only a matter of time now before the demons are no more.\n\nYou are a hero of the forest, {name}. I give you thanks on behalf of all of Ashenvale's creatures!", sourceObjectiveStatus = "unverified-source-field" }
quests[13767] = { id = 13767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Orgrimmar wolf, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Morah Worgsister at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle insticts. When the competition begins, you will be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[13768] = { id = 13768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Zul'tore at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", sourceObjectiveStatus = "unverified-source-field" }
quests[13769] = { id = 13769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Zul'tore at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13770] = { id = 13770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Zul'tore at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13771] = { id = 13771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Shadow Hunter Mezil-kree at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", progress = "Have you tested yourself in combat against the Scourge?", completion = "A good day of training will never hurt anyone. It's good to see you keeping up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13772] = { id = 13772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Darkspear raptor, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Gahju at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against other valiants will quickly teach you what you need to know to best them. Keep it up and you'll have no trouble defeating them in competition.", sourceObjectiveStatus = "unverified-source-field" }
quests[13773] = { id = 13773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Runok Wildmane at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", sourceObjectiveStatus = "unverified-source-field" }
